/** THE PENTHOUSE — what needs you this week, and the button that ends it.
 *
 *  Ordered by what is actually urgent rather than by category: events first because they expire,
 *  then problems, then the household's own state. The end-of-week button is the only irreversible
 *  control in the app and it says what it will cost before you press it. */
import { momentsOf } from "../engine/moments";
import { concludeMoment } from "../engine/deeds";
import FCTVCard from "./FCTVCard";
import AssistantCard from "./Assistant";
import { Reaction as MomentReaction, OpenMoments } from "./MomentCard";
import { useState } from "react";
import { AlertTriangle, ChevronRight, Loader2 } from "lucide-react";
import type { Route } from "../App";
import { useGame } from "../lib/game";
import { Button, Card, Empty, Fold, Meter, Money, Section, Stat } from "../lib/ui";
import { endWeek } from "../engine/week";
import { writeWeekProse } from "../engine/forge";
import { resolveEvent, EVENT_BY_ID } from "../engine/events";
import { generateDynamicEvent, resolveDynamic, dynamicReadiness } from "../engine/dynamic";
import { voiceAsk } from "../engine/asks";
import { AskList } from "./AskCard";
import StoryCard from "./StoryCard";
import WorldCard from "./WorldCard";
import Ambitions from "./Ambitions";
import { theKeeper, inHousehold } from "../engine/romance";
import { nextEvent as chainEvent, resolveChain, reversalOf, subjectOf, GESTURES, gestureAvailable, doGesture, type Reaction } from "../engine/reversal";
import { liveThreads, answerThread, describeThread } from "../engine/threads";
import { THREAD_BY_KIND } from "../data/threads";
import { SlaveHead } from "./SlaveArt";
import { read } from "../engine/obedience";
import { band, wear } from "../engine/psyche";
import { modelsAvailable } from "../config";

export default function Penthouse({ go }: { go: (r: Route) => void }) {
  const [outcomes, setOutcomes] = useState<{ id: string; chose: string; text: string; person?: string; others?: string[]; moment?: string }[]>([]);
  /** Done: the card goes, and a scene played out under it ends where it is. */
  const finish = async (o: { id: string; moment?: string }) => {
    const m = o.moment ? momentsOf(save).find((x) => x.id === o.moment) : undefined;
    setOutcomes((xs) => xs.filter((x) => x.id !== o.id));
    if (m?.open) { await concludeMoment(save, m); mutate(() => {}); }
  };
  const { save, mutate } = useGame();
  const [running, setRunning] = useState(false);
  const [inventing, setInventing] = useState(false);
  const [aftermath, setAftermath] = useState<{ line: string; reactions: Reaction[]; person?: string; others?: string[]; title?: string; chose?: string; key?: number } | null>(null);
  const dyn = dynamicReadiness(save);
  const keeper = theKeeper(save);
  const arc = save.arcology;
  const people = Object.values(save.people).filter((p) => inHousehold(save, p));
  const lastReport = save.reports.at(-1);
  const rev = reversalOf(save);
  const chain = chainEvent(save);
  const her = subjectOf(save);
  const canGesture = gestureAvailable(save);
  const threads = liveThreads(save);
  const waiting = threads.filter((t) => t.pending !== undefined);

  const flags = people
    .map((p) => ({ p, r: read(p, save.memory[p.id]) }))
    .filter((x) => x.r.flight_risk > 0.3 || x.p.psyche.state !== "intact" || x.p.health.health < -30 || x.r.fragility > 0.75)
    .sort((a, b) => b.r.flight_risk - a.r.flight_risk);

  async function runWeek() {
    setRunning(true);
    let report = null as ReturnType<typeof endWeek> | null;
    mutate((s) => { report = endWeek(s); });
    // In lean mode the week report stays as the game wrote it: no model call for the summary.
    if (report && modelsAvailable() && !save.models.lean_mode) {
      const text = await writeWeekProse(save, report);
      if (text) mutate(() => { /* report is already in the save; the prose was written onto it */ });
    }
    // Put the week's requests into their own mouths, when there is a model to do it. The payload
    // was fixed before this ran and is not passed to the model; only the wording changes.
    // One at a time: a burst of parallel calls is what trips a provider's per-minute limit.
    if (modelsAvailable() && !save.models.lean_mode && save.asks?.length) {
      const voiced: { id: string; says: string }[] = [];
      for (const a of save.asks) voiced.push({ id: a.id, says: await voiceAsk(save, a) });
      mutate((s) => { for (const v of voiced) { const a = s.asks?.find((x) => x.id === v.id); if (a) a.text = v.says; } });
    }
    setRunning(false);
    go("report");
  }

  return (
    <>
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-2.5 mb-6">
        <Stat label="cash" value={<Money n={arc.cash} />} sub={lastReport ? <>last week <Money n={lastReport.cash_end - lastReport.cash_start} sign /></> : "—"} />
        <Stat label="reputation" value={Math.round(arc.rep).toLocaleString()} sub={`standing ${arc.public_standing > 0 ? "+" : ""}${arc.public_standing}`} />
        <Stat label="prosperity" value={Math.round(arc.prosperity)} sub={`crime ${Math.round(arc.crime)}`} tone={arc.prosperity < 40 ? "bad" : undefined} />
        <Stat label="owned" value={people.length} sub={`${people.filter((p) => p.assignment === "rest").length} idle`} />
      </div>

      {keeper ? (
        <Card className="mb-6" >
          <div className="text-[11px] uppercase tracking-wider dim mb-1">she owns the arcology now</div>
          <p className="font-prose text-[15px]">
            {keeper.name} runs {arc.name}. The week below is her report. What you get is a say, when she asks for one.
          </p>
        </Card>
      ) : null}

      {/* YOUR STORY FIRST. It is the thing that is only about you. */}
      <StoryCard />

      <AssistantCard />

      <WorldCard />

      <div className="mb-6"><FCTVCard /></div>

      {/* SITUATIONS FIRST. A thread is the game telling you something it worked out about the last
          two months, which outranks anything that happened on Tuesday. */}
      {waiting.length ? (
        <Section title={waiting.length === 1 ? "Something has been going on" : "Things have been going on"}>
          <div className="space-y-3">
            {waiting.map((t) => {
              const def = THREAD_BY_KIND[t.kind]!;
              const beat = def.beats[t.pending!];
              const c = {
                s: save,
                who: Object.fromEntries(Object.entries(t.cast).map(([r, id]) => [r, save.people[id]?.name ?? "she"])),
                weeks: save.arcology.week - t.opened, heat: t.heat, facts: t.facts,
              };
              return (
                <Card key={t.id} className="border-l-2">
                  <div className="flex items-center gap-2 mb-2">
                    <span className="text-[11px] uppercase tracking-wider warn">{def.name}</span>
                    <span className="text-[11px] dim">· {c.weeks} weeks</span>
                  </div>
                  <div className="text-[13px] mb-2">{beat.title}</div>
                  <p className="font-prose text-[15px] leading-relaxed whitespace-pre-line mb-3">{beat.text?.(c)}</p>
                  <div className="flex flex-wrap gap-2">
                    {beat.options?.map((o) => (
                      <Button key={o.id} size="sm" title={o.note} onClick={() => mutate((st) => {
                        setAftermath({ line: answerThread(st, t.id, o.id).line, reactions: [], person: Object.values(t.cast)[0], others: Object.values(t.cast).slice(1), title: def.name, chose: o.label, key: Date.now() });
                      })}>{o.label}</Button>
                    ))}
                  </div>
                  {beat.options?.some((o) => o.note) ? (
                    <div className="text-[11px] dim mt-2">{beat.options.filter((o) => o.note).map((o) => `${o.label}: ${o.note}`).join(" · ")}</div>
                  ) : null}
                </Card>
              );
            })}
          </div>
        </Section>
      ) : null}

      {threads.filter((t) => t.pending === undefined && t.heat > 18).length ? (
        <Fold id="threads" title="Running" count={threads.filter((t) => t.pending === undefined && t.heat > 18).length}>
          <div className="space-y-1.5">
            {threads.filter((t) => t.pending === undefined && t.heat > 18).map((t) => {
              const d = describeThread(save, t);
              return (
                <div key={t.id} className="card-2 px-3 py-2">
                  <div className="text-[12.5px]">{d.name}{d.who.length ? <span className="dim"> · {d.who.join(" and ")}</span> : null}</div>
                  <div className="text-[11.5px] dim">{d.blurb}</div>
                </div>
              );
            })}
          </div>
        </Fold>
      ) : null}

      {chain ? (
        <Section title="Supplicationism" right={<span className="text-[11px] uppercase tracking-wider dim">deference {Math.round(rev.deference)}</span>}>
          <Card className="border-l-2">
            <div className="text-[13px] mb-2">{chain.title}</div>
            <p className="font-prose text-[15px] leading-relaxed whitespace-pre-line mb-4">{chain.text(save, her?.name)}</p>
            <div className="flex flex-wrap gap-2">
              {chain.options.map((o) => (
                <Button key={o.id} size="sm" title={o.note} onClick={() => {
                  let out: { line: string; reactions: Reaction[] } = { line: "", reactions: [] };
                  mutate((s) => { out = resolveChain(s, o.id); });
                  setAftermath(out);
                }}>{o.label}</Button>
              ))}
            </div>
            {chain.options.some((o) => o.note) ? (
              <div className="text-[11px] dim mt-2">{chain.options.filter((o) => o.note).map((o) => `${o.label}: ${o.note}`).join(" · ")}</div>
            ) : null}
          </Card>
        </Section>
      ) : null}

      {!chain && canGesture && her && rev.done.length > 0 ? (
        <Section title="In public" right={<span className="text-[11px] uppercase tracking-wider dim">deference {Math.round(rev.deference)}</span>}>
          <Card>
            <p className="font-prose text-[15px] leading-relaxed mb-3">
              The arcology takes its cue from the most recent thing it watched you do, and it has been {Math.max(0, arc.week - (rev.last_public ?? 0))} weeks.
            </p>
            <div className="flex flex-wrap gap-2">
              {GESTURES.map((g) => (
                <Button key={g.id} size="sm" title={g.note} onClick={() => {
                  let out: { line: string; reactions: Reaction[] } = { line: "", reactions: [] };
                  mutate((s) => { out = doGesture(s, g.id); });
                  setAftermath(out);
                }}>{g.label}</Button>
              ))}
            </div>
            <div className="text-[11px] dim mt-2">{GESTURES.map((g) => `${g.label}: ${g.note}${g.rep ? ` · ${g.rep} rep` : ""}`).join(" · ")}</div>
          </Card>
        </Section>
      ) : null}

      {aftermath ? (
        <Section title="What came of it" right={<Button size="sm" kind="ghost" onClick={() => setAftermath(null)}>done</Button>}>
          <Card>
            <p className="font-prose text-[15px] leading-relaxed">{aftermath.line}</p>
            {aftermath.person || modelsAvailable() ? <MomentReaction key={aftermath.key} seed={{ person: aftermath.person, others: aftermath.others, title: aftermath.title ?? "Afterwards", source: "thread", you: aftermath.chose, happened: aftermath.line }} /> : null}
            {aftermath.reactions.length ? (
              <ul className="mt-3 space-y-1.5 text-[13px]">
                {aftermath.reactions.map((rx) => (
                  <li key={rx.id} className="flex gap-2">
                    <span className="dim" style={{ color: rx.tone === "bad" ? "var(--danger)" : rx.tone === "good" ? "var(--good)" : rx.tone === "warning" ? "var(--warn)" : undefined }}>·</span>
                    <span>{rx.line}</span>
                  </li>
                ))}
              </ul>
            ) : null}
          </Card>
        </Section>
      ) : null}

      <AskList asks={save.asks ?? []} title={keeper ? "What she wants from you" : "They want something"} />

      <div className="mb-6"><OpenMoments title="Left unfinished" /></div>

      {outcomes.map((o) => (
        <Card key={o.id} className="mb-4 border-l-2 fade-in">
          <div className="player-line !mt-0 !mb-3">{o.chose}</div>
          <div className="space-y-3">
            {o.text.split(/\n\n+/).map((para, i) => <p key={i} className="font-prose text-[15px] leading-relaxed">{para}</p>)}
          </div>
          <div className="flex items-center gap-2">
            {o.person || modelsAvailable() ? <MomentReaction seed={{ person: o.person, others: o.others, title: o.chose, source: "event", you: o.chose, happened: o.text }} onOpen={(mid) => setOutcomes((xs) => xs.map((x) => (x.id === o.id ? { ...x, moment: mid } : x)))} /> : null}
            <Button size="sm" kind="primary" className="mt-3" onClick={() => void finish(o)}>Done</Button>
          </div>
        </Card>
      ))}

      {save.events.length ? (
        <Section title="Waiting on you" right={
          <Button size="sm" kind="ghost" disabled={inventing || !dyn.ready} title={dyn.note} onClick={async () => {
            setInventing(true);
            const e = await generateDynamicEvent(save);
            if (e) mutate((s) => { s.events.push(e); });
            setInventing(false);
          }}>{inventing ? "…" : "something else happens"}</Button>
        }>
          <div className="space-y-3">
            {save.events.map((e) => {
              const person = e.person ? save.people[e.person] : undefined;
              return (
                <Card key={e.id} className={e.severity === "major" ? "border-l-2" : ""}>
                  <div className="flex items-center gap-2 mb-2">
                    {e.severity === "major" ? <AlertTriangle size={14} className="bad" /> : null}
                    <span className="text-[11px] uppercase tracking-wider dim">{e.severity}</span>
                    {person ? <span className="chip">{person.name}</span> : null}
                  </div>
                  <p className="font-prose text-[15px] leading-relaxed mb-3">{e.seed}</p>
                  <div className="flex flex-wrap gap-2">
                    {(e.kind === "dynamic" ? e.options : EVENT_BY_ID[e.kind]?.options ?? e.options).map((o) => (
                      <Button key={o.id} size="sm" title={o.note} onClick={() => {
                        let text = "";
                        mutate((s) => { text = e.kind === "dynamic" ? resolveDynamic(s, e, o.id) : resolveEvent(s, e, o.id); });
                        setOutcomes((xs) => [...xs, { id: e.id, chose: o.label, text, person: e.person, others: e.other ? [e.other] : undefined }]);
                      }}>
                        {o.label}
                      </Button>
                    ))}
                  </div>
                  {e.options.some((o) => o.note) ? (
                    <div className="text-[11px] dim mt-2">{e.options.filter((o) => o.note).map((o) => `${o.label}: ${o.note}`).join(" · ")}</div>
                  ) : null}
                </Card>
              );
            })}
          </div>
        </Section>
      ) : null}

      {save.notifications.filter((n) => !n.seen).length ? (
        <Fold id="notices" count={save.notifications.filter((n) => !n.seen).length} title="Since you last looked" right={
          <Button size="sm" kind="ghost" onClick={() => mutate((s) => { for (const n of s.notifications) n.seen = true; })}>mark read</Button>
        }>
          <div className="space-y-1.5">
            {save.notifications.filter((n) => !n.seen).slice(-10).reverse().map((n) => (
              <div key={n.id} className="card-2 px-3 py-2 flex gap-3 items-baseline">
                <span className="font-mono text-[11px] dim shrink-0">wk {n.week}</span>
                <span className="text-[12.5px] flex-1" style={{ color: n.kind === "danger" ? "var(--danger)" : n.kind === "warning" ? "var(--warn)" : n.kind === "good" ? "var(--good)" : undefined }}>
                  {n.text}
                </span>
                {n.person && save.people[n.person] ? <span className="text-[11px] dim shrink-0">{save.people[n.person].name}</span> : null}
              </div>
            ))}
          </div>
        </Fold>
      ) : null}

      {!save.events.length && dyn.ready ? (
        <Section title="Quiet week" right={
          <Button size="sm" disabled={inventing || !dyn.ready} title={dyn.note} onClick={async () => {
            setInventing(true);
            const e = await generateDynamicEvent(save);
            if (e) mutate((s) => { s.events.push(e); });
            setInventing(false);
          }}>{inventing ? <><Loader2 size={13} className="animate-spin" /> inventing</> : "make something happen"}</Button>
        }>
          <Card className="text-[12px] dim">{dyn.note}</Card>
        </Section>
      ) : null}

      {lastReport?.problems.length ? (
        <Section title="Problems">
          <Card>
            <ul className="space-y-1.5 text-[13px]">
              {lastReport.problems.map((p, i) => <li key={i} className="flex gap-2"><span className="bad">·</span>{p}</li>)}
            </ul>
          </Card>
        </Section>
      ) : null}

      <Fold id="ambitions" title="What you're after" defaultOpen={false}>
        <Ambitions />
      </Fold>

      <Fold id="flags" count={flags.length} title="Who needs looking at" right={<Button size="sm" kind="ghost" onClick={() => go("people")}>all {people.length} <ChevronRight size={13} /></Button>}>
        {flags.length ? (
          <div className="space-y-2">
            {flags.slice(0, 6).map(({ p, r }) => (
              <Card key={p.id} className="flex items-center gap-3 py-3" onClick={() => go("people")}>
                <SlaveHead person={p} size={40} />
                <div className="flex-1 min-w-0">
                  <div className="text-[13px]">{p.name} <span className="dim">· {band(p.psyche)}</span></div>
                  <div className="text-[11.5px] dim truncate">
                    {p.psyche.state !== "intact" ? `${p.psyche.state}. ` : ""}
                    {r.flight_risk > 0.3 ? `flight risk ${Math.round(r.flight_risk * 100)}%. ` : ""}
                    {r.fragility > 0.75 ? `${Math.round(r.fragility * 100)}% of her obedience is fear. ` : ""}
                    {p.health.health < -30 ? `health ${p.health.health}. ` : ""}
                    {wear(p.psyche) > 0.6 ? "worn down." : ""}
                  </div>
                </div>
                <div className="w-24 shrink-0"><Meter value={r.devotion} range={[-100, 100]} label="devotion" /></div>
              </Card>
            ))}
          </div>
        ) : <Empty>Nobody needs you this week.</Empty>}
      </Fold>

      <Section title="The week">
        <Card>
          <div className="flex items-center gap-4 flex-wrap">
            <div className="flex-1 min-w-[220px]">
              <div className="text-[13px] mb-1">End week {arc.week}</div>
              <div className="text-[11.5px] dim">
                {save.orders.filter((o) => o.enabled).length} standing orders armed.
              </div>
            </div>
            <Button kind="primary" onClick={runWeek} disabled={running}>
              {running ? <><Loader2 size={14} className="animate-spin" /> running</> : "End the week"}
            </Button>
          </div>
        </Card>
      </Section>
    </>
  );
}
